// T-346: goldens for the online-helper states (ar/en x light/dark). Tagged;
// PNGs are generated by CI and not committed from a local run.
@Tags(['golden'])
library;

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/core/llm/llm_quota_snapshot.dart';
import 'package:zaghlol/features/ask/application/llm_ask_flow.dart';
import 'package:zaghlol/features/ask/presentation/ask_screen.dart';
import 'package:zaghlol_parsing/zaghlol_parsing.dart';

import 'llm_ask_states_test.dart' show Script, pumpLlm;

final _q = LlmQuotaSnapshot(
  limit: 5,
  remaining: 3,
  resetsAt: DateTime.utc(2026, 11, 30, 22),
);

Stream<AskLlmState> _one(AskLlmState s) => Stream.value(s);

void main() {
  final states = <String, Script>{
    'sending': (_, _) async* {
      yield const AskLlmSending();
      // Never completes: a timer would be left pending at the end of the test.
      await Completer<void>().future;
    },
    'error': (_, _) => _one(const AskLlmFailed(AskLlmFailure.timeout)),
    'paused': (_, _) => _one(const AskLlmPaused()),
    'clarify': (_, _) => _one(
      const AskLlmClarify(
        MaskUnresolved(MaskUnresolvedReason.ambiguousCard, [
          MaskAccount(id: 'a1', label: 'Card A', last4: '1234'),
          MaskAccount(id: 'a2', label: 'Card B', last4: '1234'),
        ]),
      ),
    ),
    'exhausted_free': (_, _) => _one(AskLlmQuotaOut(_q)),
  };
  for (final locale in const [Locale('ar', 'EG'), Locale('en')]) {
    for (final dark in const [false, true]) {
      final name = '${locale.languageCode}_${dark ? 'dark' : 'light'}';
      testWidgets('S-50 llm idle $name', (t) async {
        await pumpLlm(
          t,
          states['error']!,
          locale: locale,
          dark: dark,
          quota: _q,
        );
        await expectLater(
          find.byType(AskScreen),
          matchesGoldenFile('goldens/ask_llm_idle_$name.png'),
        );
      });
      testWidgets('S-50 llm idle 130 $name', (t) async {
        await pumpLlm(
          t,
          states['error']!,
          locale: locale,
          dark: dark,
          quota: _q,
          scale: 1.3,
        );
        await expectLater(
          find.byType(AskScreen),
          matchesGoldenFile('goldens/ask_llm_idle130_$name.png'),
        );
      });
      for (final e in {
        ...states,
        'exhausted_gold': states['exhausted_free']!,
      }.entries) {
        testWidgets('S-50 llm ${e.key} $name', (t) async {
          await pumpLlm(
            t,
            e.value,
            locale: locale,
            dark: dark,
            quota: _q,
            gold: e.key == 'exhausted_gold',
          );
          await t.enterText(find.byType(TextField), 'hello there');
          await t.pump();
          await t.tap(find.byKey(const ValueKey('ask-send')));
          await t.pump();
          await t.pump();
          await expectLater(
            find.byType(AskScreen),
            matchesGoldenFile('goldens/ask_llm_${e.key}_$name.png'),
          );
        });
      }
    }
  }
}
